using NUnit.Framework;
using SaferAccessors.Tests;

namespace SaferAccessors.Analysis.Tests.Generators;

internal static class PropertyAccessorGeneratorTests
{
	[Test]
	public static async Task GenerateWithInstanceGetAsync()
	{
		var code =
			"""
			using SaferAccessors;

			[assembly: UnsafeAccessorMap(typeof(Test))]

			public class Test
			{
				private int Id { get; }
			}
			""";

		var generatedCode =
			"""
			// <auto-generated/>
			
			#nullable enable
			
			public static partial class TestExtensions
			{
				extension(global::Test self)
				{
					public int Id
					{
						get => TestAccessors.GetId(self);
					}
				}
				
				private static partial class TestAccessors
				{
					[global::System.Runtime.CompilerServices.UnsafeAccessor(global::System.Runtime.CompilerServices.UnsafeAccessorKind.Method, Name = "get_Id")]
					public static extern int GetId(global::Test self);
					
				}
				
			}
			
			""";

		await TestAssistants.RunGeneratorAsync<SaferAccessorsGenerator>(code,
			[($"Test_Accessors.g.cs", generatedCode)],
			[]);
	}

